    private static String family(String role) {
        switch (role) {
            case "display": return new String[]{"Fraunces", "3270 Nerd Font", "Fraunces", "Fraunces"}[i()];
            case "strong": return new String[]{"Space Grotesk", "3270 Nerd Font", "Space Grotesk", "Space Grotesk"}[i()];
            case "mono": return new String[]{"Space Mono", "3270 Nerd Font Mono", "3270 Nerd Font Mono", "Space Mono"}[i()];
            default: return new String[]{"Space Grotesk", "3270 Nerd Font", "Space Grotesk", "Space Grotesk"}[i()];
        }
    }
    private static int px(String size) {
        switch (size) {
            case "label": return new int[]{11, 11, 11, 11}[i()];
            case "small": return new int[]{12, 12, 12, 12}[i()];
            case "ui": return new int[]{14, 14, 14, 14}[i()];
            case "body": return new int[]{16, 15, 15, 16}[i()];
            case "h3": return new int[]{20, 18, 19, 20}[i()];
            case "h2": return new int[]{48, 30, 38, 48}[i()];
            case "h1": return new int[]{96, 56, 72, 96}[i()];
            case "stat": return new int[]{34, 30, 32, 34}[i()];
            default: return 14;
        }
    }

    /** Register mono-ui's TTFs so the families above resolve. Pass null to rely on installed fonts. */
    public static int loadFonts(Path dir) {
        if (dir == null || !Files.isDirectory(dir)) return 0;
        int n = 0;
        GraphicsEnvironment ge = GraphicsEnvironment.getLocalGraphicsEnvironment();
        try (DirectoryStream<Path> ds = Files.newDirectoryStream(dir, "*.ttf")) {
            for (Path p : ds) {
                try { if (ge.registerFont(Font.createFont(Font.TRUETYPE_FONT, p.toFile()))) n++; }
                catch (FontFormatException | IOException ignored) { }
            }
        } catch (IOException ignored) { }
        return n;
    }

    public static Font font(String role, String size, int style) {
        return new Font(family(role), style, px(size));
    }

